import{_ as o,o as t,c as a,ae as r}from"./chunks/framework.EHGTsUvI.js";const c=JSON.parse('{"title":"Log Storage","description":"","frontmatter":{"title":"Log Storage"},"headers":[],"relativePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md","filePath":"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md"}'),i={name:"Main/Main/GeneralKnowledge/Factorys&Utilities/Utilities/logstorage.md"};function s(l,e,n,g,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="log-storage" tabindex="-1">Log Storage <a class="header-anchor" href="#log-storage" aria-label="Permalink to &quot;Log Storage&quot;">​</a></h1><p>Log Storage is a storage building used to store harvested <strong>Logs</strong>, allowing players to keep large quantities of logs for later use.</p><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Log Storage is used to store harvested logs without needing to keep them inside trailers or other vehicles.</p><p>It is particularly useful for storing logs that will later be used in <strong>LumberCo</strong> or other production activities.</p><h2 id="how-to-use" tabindex="-1">How to Use <a class="header-anchor" href="#how-to-use" aria-label="Permalink to &quot;How to Use&quot;">​</a></h2><h3 id="_1-place-the-log-storage" tabindex="-1">1. Place the Log Storage <a class="header-anchor" href="#_1-place-the-log-storage" aria-label="Permalink to &quot;1. Place the Log Storage&quot;">​</a></h3><p>Purchase and place the Log Storage on your farm.</p><h3 id="_2-load-logs" tabindex="-1">2. Load Logs <a class="header-anchor" href="#_2-load-logs" aria-label="Permalink to &quot;2. Load Logs&quot;">​</a></h3><p>Bring harvested logs to the Log Storage and unload them into the storage area.</p><h3 id="_3-store-logs" tabindex="-1">3. Store Logs <a class="header-anchor" href="#_3-store-logs" aria-label="Permalink to &quot;3. Store Logs&quot;">​</a></h3><p>The logs will remain stored inside the storage until they are needed.</p><h3 id="_4-remove-logs" tabindex="-1">4. Remove Logs <a class="header-anchor" href="#_4-remove-logs" aria-label="Permalink to &quot;4. Remove Logs&quot;">​</a></h3><p>When required, remove the stored logs and load them onto a suitable vehicle or trailer for transportation or production.</p><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Information</th><th>Details</th></tr></thead><tbody><tr><td>Purchase Price</td><td><strong>To be confirmed</strong></td></tr><tr><td>Storage Capacity</td><td><strong>To be confirmed</strong></td></tr></tbody></table><blockquote><p><strong>Note:</strong> The current purchase price and storage capacity should be confirmed in-game before being added as fixed values.</p></blockquote><h2 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements&quot;">​</a></h2><ul><li>No special license required.</li><li>Suitable space on your farm.</li><li>Logs to be stored.</li></ul><h2 id="useful-information-tips" tabindex="-1">Useful Information &amp; Tips <a class="header-anchor" href="#useful-information-tips" aria-label="Permalink to &quot;Useful Information &amp; Tips&quot;">​</a></h2><ul><li>Log Storage allows you to store logs between harvesting trips.</li><li>Useful for stockpiling logs for <strong>LumberCo</strong>.</li><li>Helps reduce the need to keep logs inside trailers.</li><li>Useful for players who regularly harvest large quantities of logs.</li><li>Keeping logs stored on your farm can make transporting materials to LumberCo more convenient.</li><li>Storage capacity may vary depending on the current game version.</li></ul><blockquote><p><strong>Note:</strong> Storage prices, capacities, and functionality may change with future game updates.</p></blockquote>',22)])])}const p=o(i,[["render",s]]);export{c as __pageData,p as default};
